const T1="Part 1 · Building a Fair Study",T2="Part 2 · The Sociological Perspective",T3="Part 3 · Research Methods",T4="Part 4 · Theories & Founders";
const MOVIE=/truman|christof|seahaven|town|show|camera|warning|bridge|water|boat|storm|sea|ocean|father|dad|meryl|marlon|sylvia|advert|\bads?\b|news|radio|sky|door|routine|fear|scared|profit|money|paid|job|work|family|school|rule|leave|travel|island|fiji|actor|cast|crew|director|viewer|poster|route|network|lie|lying/i;
const chapters=[
{title:"Prove It, Truman",kicker:"Test Part 1 · Building a Fair Study",icon:"✦",caption:"STAGE LIGHT DOWN • 7:02 AM",color:"linear-gradient(135deg,#2a7ba5,#76d5df)",scenes:[
{type:"mc",speaker:"TRUMAN",story:"A stage light crashes onto Truman’s street. It’s labeled <b>Sirius</b>, the name of a star. The radio says a plane dropped it. Truman doesn’t buy it. He needs a <b>hypothesis</b>: a guess you can test with evidence.",prompt:"Which one is a <b>testable hypothesis</b>?",choices:["If Truman changes his route, more people will appear near him.","If a town is fake, then it is a terrible place to live.","If Truman is unhappy, he should leave Seahaven right away.","Truman is braver than anyone else who lives in Seahaven."],answer:0,why:"A testable hypothesis predicts something you can count or check. “Terrible,” “should,” and “braver” are opinions. You can’t measure them.",topic:T1,idea:"what makes a hypothesis testable",evidence:"The falling star"},
{type:"sort",speaker:"TRUMAN’S PLAN",story:"Truman plans two tests. <b>Route test:</b> drive a random route, count who shows up. <b>Poster test:</b> do people who see more travel-warning posters say they’ll never leave? The <b>IV</b> is the cause you change. The <b>DV</b> is the result you measure.",prompt:"Sort each card: IV or DV?",categories:["IV · THE CAUSE","DV · THE RESULT"],items:[{text:"Route test: whether Truman drives a random route",answer:0},{text:"Route test: how many people show up near him",answer:1},{text:"Poster test: how many travel posters a person sees",answer:0},{text:"Poster test: whether that person says they’d ever leave",answer:1}],why:"The <b>independent variable (IV)</b> is the cause you change or compare: the route, the posters. The <b>dependent variable (DV)</b> is the result you measure: who shows up, plans to leave.",topic:T1,idea:"IV (cause) vs. DV (result)",evidence:"Variables locked"},
{type:"mc",speaker:"MARLON",story:"Truman spots a pattern: every time he talks about leaving for <b>Fiji</b>, Meryl changes the subject to having a baby. Marlon shrugs: “Huh. Guess Fiji talk makes her want a baby.”",prompt:"What’s wrong with Marlon’s idea?",choices:["Marriage is too private a topic for anyone to study.","A pattern alone doesn’t prove what caused it.","Truman only noticed it at home, never at work.","Only a psychologist could study Meryl’s choices."],answer:1,why:"Two things happening together is a <b>correlation</b>, not proof of a cause. Marlon guessed the cause was Meryl’s feelings. The real cause was hidden: the control room feeds Meryl her lines.",topic:T1,idea:"pattern vs. cause",evidence:"The hidden cause"},
{type:"sort",speaker:"ETHICS BOARD",story:"Sociologists must protect the people they study. <b>Informed consent</b> = you know about the study and agree to it. <b>Confidentiality</b> = your private info stays private. <b>Right to withdraw</b> = you can quit any time.",prompt:"Truman’s whole life is one giant study. Which protection does each event break <b>most clearly</b>?",categories:["INFORMED CONSENT","CONFIDENTIALITY","RIGHT TO WITHDRAW"],items:[{text:"Nobody ever told Truman about the show or asked him to agree.",answer:0},{text:"Truman’s most private moments are shown to strangers around the world.",answer:1},{text:"When Truman tries to drive away, the show blocks the road with a fake fire.",answer:2}],why:"Consent = knowing and agreeing. Confidentiality = keeping private info private. Right to withdraw = being free to quit. Seahaven breaks all three.",topic:T1,idea:"research ethics",evidence:"Broken protections"},
{type:"fill",speaker:"TRANSMISSION · EXPLAIN IT 1",story:"Your test has this kind of answer. Fill in the blanks. A few words each.",prompt:"Write a <b>hypothesis</b> about Seahaven. Then name the <b>IV</b> (the cause) and the <b>DV</b> (the result).",parts:["In Seahaven, people who see more ",{sel:["travel-warning posters","of Meryl’s product ads","news about storms at sea"],sample:0}," will ",{txt:"what will happen?",min:2,sample:"be less likely to leave"},". The IV is ",{txt:"the cause",min:2,sample:"how many posters they see"}," and the DV is ",{txt:"the result",min:2,sample:"whether they try to leave"},"."],diff:[3,5,"Your IV and DV can’t be the same thing. The IV is the cause. The DV is the result."],topic:T1,key:"e1",short:"Explain It 1 · Hypothesis + IV and DV",label:"Explain It 1 · hypothesis + IV/DV (Soc.1)",evidence:"Explain It 1 sent"}]},

{title:"Zoom Out",kicker:"Test Part 2 · The Sociological Perspective",icon:"◉",caption:"LANCASTER SQUARE • NOON",color:"linear-gradient(135deg,#54266f,#ee686d)",scenes:[
{type:"mc",speaker:"CAMERA 12",story:"Truman has lived on one island for 30 years and never left. Why not?",prompt:"Which question is the most <b>sociological</b>?",choices:["Did losing his dad leave Truman with a fear of water?","Do the town’s news, ads, and neighbors all say to stay?","Do the town’s scary stories give Truman nightmares?","Does Truman clearly remember his father’s boat trip?"],answer:1,why:"Sociology studies <b>people in groups and the patterns they share</b>: the people, rules, and messages around a person. Fears, dreams, and memories are what a psychologist looks at.",topic:T2,idea:"what sociology studies (groups and patterns)",evidence:"Two investigator lenses"},
{type:"sort",speaker:"CASE TRAINING",story:"C. Wright Mills said some problems belong to one person. Others come from the way society is set up. Linking the two is the <b>sociological imagination</b>.",prompt:"Sort each one.",categories:["PERSONAL TROUBLE","PUBLIC ISSUE"],items:[{text:"Truman can’t sleep after a fight with Meryl.",answer:0},{text:"The show’s ads, news, and schools all teach that travel is deadly.",answer:1},{text:"An actor forgets her line during a scene.",answer:0},{text:"Viewers all over the world watch one man’s private life for fun.",answer:1}],why:"A <b>personal trouble</b> comes from one person’s own life. A <b>public issue</b> comes from a pattern built into society.",topic:T2,idea:"personal trouble vs. public issue",evidence:"Trouble-or-issue decoder"},
{type:"mc",speaker:"MERYL",story:"Truman says something is wrong with Seahaven. Meryl, his mom, and his best friend Marlon all tell him it’s in his head. Soon Truman starts doubting himself.",prompt:"Why would a <b>sociologist</b> care about this scene?",choices:["It shows how one person’s eyes judge what they see.","It shows how money decides what people choose to buy.","It shows a group can change what a person believes.","It shows how laws punish people who choose to speak out."],answer:2,why:"When everyone around you agrees, it’s hard to trust yourself. That’s <b>conformity</b>: the group shapes the person. Groups are what sociology studies.",topic:T2,idea:"groups shaping people",evidence:"Pressure from the crowd"},
{type:"fill",speaker:"TRANSMISSION · EXPLAIN IT 2",story:"Connect one person’s trouble to the bigger picture. That’s the <b>sociological imagination</b>.",prompt:"Pick a personal trouble. Then connect it to a <b>public issue</b> in Seahaven.",parts:[{sel:["Truman’s fear of water","Truman not getting a ticket to Fiji","Marlon lying to Truman"],sample:0}," looks like one person’s trouble, but it connects to the public issue of ",{txt:"the bigger problem",min:2,sample:"the show controlling the news",need:[/show|christof|news|\bads?\b|advert|media|cast|actors?|crew|network|company|control|town|everyone|whole|system|warning|poster|camera|tv|lie|lying|script/i,"Make the public issue bigger than Truman: the show, the news, the cast, or the whole town."]}," because ",{txt:"why?",min:3,sample:"the whole town is built to keep him from leaving"},"."],topic:T2,key:"e2",short:"Explain It 2 · Personal trouble → public issue",label:"Explain It 2 · trouble → public issue (Soc.2)",evidence:"Explain It 2 sent"}]},

{title:"Gather the Evidence",kicker:"Test Part 3 · Research Methods",icon:"◎",caption:"HIDDEN CAMERA NETWORK • ONLINE",color:"linear-gradient(135deg,#244275,#528cf0)",scenes:[
{type:"sort",speaker:"METHOD SELECT",story:"Different questions need different tools. <b>Survey</b> = same questions to lots of people. <b>Interview</b> = a long talk with follow-ups. <b>Observation</b> = watch what people do. <b>Content analysis</b> = study TV, ads, or posts. <b>Experiment</b> = change one thing and see what happens.",prompt:"Which method fits each question best?",categories:["SURVEY","INTERVIEW","OBSERVATION","CONTENT ANALYSIS","EXPERIMENT"],items:[{text:"What percent of viewers want Truman set free?",answer:0},{text:"Why did Sylvia risk everything to warn Truman?",answer:1},{text:"Where does Truman go each day, and who is waiting there?",answer:2},{text:"How often does the show sneak product ads into scenes?",answer:3},{text:"Does a scary news report make Truman less likely to travel?",answer:4}],why:"“What percent” → survey. “Why” for one person → interview. “What do people actually do” → observation. Patterns in TV or ads → content analysis. Does X cause Y → experiment.",topic:T3,idea:"which method fits the question",evidence:"Complete method kit"},
{type:"mc",speaker:"TRUTALK",story:"Imagine <b>TruTalk</b>, the show’s own talk program, asks callers: “Should the show go on?” 50,000 people phone in, and 95% say yes.",prompt:"Why could this poll be <b>wrong</b> about what everyone thinks?",choices:["50,000 answers is too few to mean anything.","Only people already watching TruTalk could call.","Callers changed their minds after the show ended.","Phone polls can only count yes-or-no answers."],answer:1,why:"Lots of answers don’t help if you asked the wrong people. TruTalk callers leave out everyone who doesn’t watch, or thinks the show is wrong.",topic:T3,idea:"who a sample leaves out",evidence:"The callers-only poll"},
{type:"mc",speaker:"SURVEY DESK",story:"A viewer survey finds that 7 out of 10 viewers watch the show every single day.",prompt:"What is this number <b>best</b> at showing?",choices:["Exactly why each viewer keeps watching","How common it is to watch every day","That the show’s ads cause people to watch","How Truman feels about being watched"],answer:1,why:"Surveys are great at showing <b>how common</b> something is. They’re weak at showing <b>why</b>. To learn why, add interviews.",topic:T3,idea:"what a survey number can show",evidence:"7 out of 10"},
{type:"fill",speaker:"TRANSMISSION · EXPLAIN IT 3",story:"Pick a question, pick the method that fits it, then say one thing it does well and one thing it can’t do.",prompt:"Choose a research question and a method. Then give a <b>strength</b> and a <b>limit</b>.",parts:["To find out ",{sel:["why cast members keep lying to Truman","how viewers act while they watch","what percent of viewers think the show is wrong"],sample:0},", I would use ",{sel:["a survey","interviews","observation","content analysis","an experiment"],sample:1},". One strength is ",{txt:"what it does well",min:3,sample:"I can hear their real reasons"},", but one limit is ",{txt:"what it can’t do",min:3,sample:"I can only talk to a few people"},"."],match:[1,3,{0:[1],1:[2],2:[0]},"Check your method. A “why” question → interviews. “How people act” → observation. “What percent” → a survey."],topic:T3,key:"e3",short:"Explain It 3 · Method + strength + limit",label:"Explain It 3 · method + strength + limit (Soc.3)",evidence:"Explain It 3 sent"}]},

{title:"Inside the Control Room",kicker:"Test Part 4 · Theories & Founders",icon:"⚖",caption:"CONTROL ROOM • INSIDE THE MOON",color:"linear-gradient(135deg,#7b2228,#ef5e4f)",scenes:[
{type:"sort",speaker:"ARCHIVE",story:"Truman finds the founders’ files. Quick refresher: <b>Comte</b> named sociology. <b>Marx</b> = owners vs. workers. <b>Durkheim</b> = shared rules hold us together. <b>Weber</b> = the meaning behind what people do.",prompt:"Which founder would say each thing about Seahaven?",categories:["COMTE","MARX","DURKHEIM","WEBER"],items:[{text:"Don’t trust gut feelings about the town. Study it with evidence, like a scientist.",answer:0},{text:"Christof and the network get rich. Truman does the work but has no say.",answer:1},{text:"Smiling, waving, and the same daily routines hold the town together.",answer:2},{text:"To understand the cast, find out why they act and what it means to them.",answer:3}],why:"<b>Comte</b>: study society with evidence. <b>Marx</b>: owners vs. workers. <b>Durkheim</b>: shared rules and bonds hold society together. <b>Weber</b>: the meaning behind what people do.",topic:T4,idea:"the founders",evidence:"The founders’ files",ability:"FOUNDER FILES UNLOCKED"},
{type:"mc",speaker:"STORM WARNING",story:"A TV company <b>adopted</b> Truman as a baby. Christof controls the set, the news, and the weather. The show makes huge money from ads. Truman gets no say.",prompt:"Which theory <b>best</b> explains this?",choices:["Functionalism","Conflict theory","Symbolic interactionism","The sociological imagination"],answer:1,why:"<b>Conflict theory</b> looks at unequal power: who controls things and who benefits. Christof and the company have the power. Truman has none.",topic:T4,idea:"conflict theory",evidence:"Who profits?"},
{type:"mc",speaker:"BLACKOUT",story:"Truman sneaks out through his basement and vanishes from camera. The broadcast cuts off. The whole cast drops their scenes to search. Christof makes the sun rise in the middle of the night to find him.",prompt:"Which theory <b>best</b> explains why one missing part stopped everything?",choices:["Conflict theory","Symbolic interactionism","Functionalism","The sociological imagination"],answer:2,why:"<b>Functionalism</b>: every part depends on the others. When one key part breaks, the whole system stalls.",topic:T4,idea:"functionalism",evidence:"The blackout"},
{type:"mc",speaker:"EXIT DOOR",story:"For 30 years, Truman’s sky meant home and safety. When his boat hits the painted wall, the same sky means a lie. His cheerful “Good morning!” becomes a goodbye.",prompt:"Which theory <b>best</b> explains this change?",choices:["Conflict theory","Functionalism","The sociological imagination","Symbolic interactionism"],answer:3,why:"<b>Symbolic interactionism</b> studies symbols and everyday interactions, and how their meanings are made and changed.",topic:T4,idea:"symbolic interactionism",evidence:"The door in the sky"},
{type:"fill",speaker:"TRANSMISSION · EXPLAIN IT 4",story:"Last one. Then the exit door.",prompt:"Pick a theory and a situation. Explain it with that theory and one detail from the movie.",parts:[{sel:["Functionalism","Conflict theory","Symbolic interactionism"],sample:1}," would say ",{sel:["Truman stayed in Seahaven so long","the actors keep playing along"],sample:0}," because ",{txt:"use your theory",min:3,sample:"Christof had all the power and controlled what Truman knew"},". One detail from the movie is ",{txt:"something that happened",min:3,sample:"Christof sent a storm to stop Truman’s boat",need:[MOVIE,"Add a real detail from the movie: a person, a place, or something that happened."]},"."],topic:T4,key:"e4",short:"Explain It 4 · Use a theory to explain the movie",label:"Explain It 4 · apply a theory (Soc.4)",evidence:"Explain It 4 sent"}]}
];

// =====================================================================
//  ENGINE (rebuilt 11/2/2026)
//  - Choices shuffle on load and reshuffle after every wrong pick (no red left behind).
//  - A wrong pick costs something: Christof's Control rises, the signal jams for a few
//    seconds, no evidence for that clue, and the clue counts against the exit door.
//  - The exit door opens at 70% first-try. Below that, the student fixes every missed
//    clue (each one right on the first try) before the door opens.
//  - The whole run saves on this device, so a refresh picks up where the student stopped.
// =====================================================================
const PASS=0.7,JAM_SECONDS=4,RUN_KEY="seahaven-run-v4",RUNS_KEY="seahaven-runs";
const state={chapter:0,scene:0,correct:0,possible:0,evidence:[],abilities:[],topicScores:{},topicPossible:{},name:"",sound:true,attempts:0,control:15,glitches:1,inClear:false,startTime:0,timer:null,elapsedBefore:0,sortIndex:0,sortFirst:true,sequence:[],multi:new Set(),sceneMissed:false,sceneDone:false,reviewMisses:0,wipeNote:false,blocked:[],phase:"start",missed:[],reviewQueue:[],reviewTotal:0,reviewRounds:0,reviewFixed:0,reviewDone:false,turnedIn:false,finalTime:"",run:1,jammed:false,order:null,writing:{},drafts:{},fills:{}};
const $=id=>document.getElementById(id),screens={start:$("start-screen"),game:$("game-screen"),end:$("end-screen")},totalScenes=chapters.reduce((n,c)=>n+c.scenes.length,0);
function shuffle(a){const b=a.slice();for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function freshOrder(n,old){let o=shuffle([...Array(n).keys()]);if(old&&n>1&&o.join()===old.join())o.push(o.shift());return o}
function showScreen(name){Object.values(screens).forEach(s=>s.classList.remove("active"));screens[name].classList.add("active");window.scrollTo({top:0,behavior:"smooth"})}
function current(){return chapters[state.chapter].scenes[state.scene]}
function progressIndex(){let n=0;for(let i=0;i<state.chapter;i++)n+=chapters[i].scenes.length;return n+state.scene}
function fmtTime(sec){return `${String(Math.floor(sec/60)).padStart(2,"0")}:${String(sec%60).padStart(2,"0")}`}
function elapsed(){return state.elapsedBefore+(state.startTime?Math.floor((Date.now()-state.startTime)/1000):0)}
function beginTimer(){clearInterval(state.timer);state.startTime=Date.now();$("time-value").textContent=fmtTime(elapsed());state.timer=setInterval(()=>{$("time-value").textContent=fmtTime(elapsed());if(elapsed()%15===0)save()},1000)}
function buildMap(){$("chapter-list").innerHTML=chapters.map((c,i)=>`<li data-i="${i}">${c.title}</li>`).join("")}
function inReview(){return state.phase==="review"}
function updateHUD(){let percent=Math.round(progressIndex()/totalScenes*100);if(state.inClear)percent=Math.round((progressIndex()+1)/totalScenes*100);if(state.phase==="locked"||state.phase==="review")percent=95;if(state.phase==="done")percent=100;$("meter-fill").style.width=percent+"%";$("meter-value").textContent=percent+"%";$("control-fill").style.width=state.control+"%";$("control-value").textContent=state.control+"%";$("evidence-count").textContent=state.evidence.length;$("correct-count").textContent=`${state.correct}/${state.possible}`;$("hint-count").textContent=state.glitches;$("hint-btn").classList.toggle("hidden",state.glitches<1||state.inClear||state.phase!=="play");[...$("chapter-list").children].forEach((li,i)=>li.className=state.phase!=="play"?"done":i<state.chapter?"done":i===state.chapter?"active":"")}
function renderEvidence(){$("evidence-board").innerHTML=state.evidence.length?state.evidence.slice(-5).map(e=>`<div class="evidence-chip"><span>✦</span>${e}</div>`).join(""):"<p>Clues you uncover will appear here.</p>";$("abilities").innerHTML=state.abilities.map(a=>`<div class="ability">⚡ ${a}</div>`).join("")}
function missionLabel(type){return({mc:"DECISION",sort:"SORTING MISSION",sequence:"ORDER THE STEPS",multi:"SELECT ALL THAT APPLY",fill:"EXPLAIN IT · TEST PRACTICE"})[type]}

// ---------- Save / restore (this device) ----------
function save(){try{const o={};["chapter","scene","correct","possible","evidence","abilities","topicScores","topicPossible","name","control","glitches","inClear","sceneMissed","blocked","phase","missed","reviewQueue","reviewTotal","reviewRounds","reviewFixed","reviewDone","turnedIn","finalTime","run","reviewMisses","sceneDone","writing","drafts","fills"].forEach(k=>o[k]=state[k]);o.elapsed=elapsed();o.v=4;localStorage.setItem(RUN_KEY,JSON.stringify(o))}catch{}}
function loadRun(){try{const o=JSON.parse(localStorage.getItem(RUN_KEY));if(o&&o.v===4&&o.phase&&o.phase!=="start")return o}catch{}return null}
function clearRun(){try{localStorage.removeItem(RUN_KEY)}catch{}}
function restore(o){Object.assign(state,o);state.elapsedBefore=o.elapsed||0;state.startTime=0;state.multi=new Set();state.sequence=[];state.order=null;state.jammed=false;state.writing=o.writing||{};state.drafts=o.drafts||{};state.fills=o.fills||{}}

// ---------- One scene ----------
function renderScene(restoring){const ch=chapters[state.chapter],s=current();if(!restoring){state.sceneMissed=false;state.blocked=[];state.sceneDone=false}state.attempts=state.sceneMissed?1:0;state.hinted=state.blocked.length>0;state.sortIndex=0;state.sortFirst=!state.sceneMissed;state.sequence=[];state.multi=new Set();state.order=null;state.jammed=false;
 $("chapter-kicker").textContent=inReview()?`CASE REVIEW • CLUE ${state.reviewTotal-state.reviewQueue.length+1} OF ${state.reviewTotal}`:`CHAPTER ${state.chapter+1} OF ${chapters.length} • ${ch.kicker.toUpperCase()}`;$("chapter-title").textContent=ch.title;$("scene-number").textContent=String(progressIndex()+1).padStart(2,"0");$("scene-icon").textContent=ch.icon;$("scene-caption").textContent=ch.caption;$("scene-visual").style.background=ch.color;$("story-text").innerHTML=`<div class="speaker"><div class="portrait">${s.speaker[0]}</div><div class="bubble"><b>${s.speaker}</b>${s.story}</div></div>`;$("feedback").className="feedback";$("feedback").innerHTML="";$("continue-btn").classList.add("hidden");$("continue-btn").disabled=false;$("continue-btn").textContent="Continue →";renderChallenge();try{document.querySelector(".scene-card").scrollIntoView({block:"start"})}catch{}if(restoring&&state.sceneDone&&s.type==="fill"){showModel(s);$("continue-btn").classList.remove("hidden")}else if(restoring&&state.sceneDone){$("challenge-area").querySelectorAll("button").forEach(b=>b.disabled=true);flash(`<strong>Evidence filed.</strong> <span>${s.why}</span>`,true);$("continue-btn").classList.remove("hidden")}updateHUD();save()}
function renderChallenge(){const s=current(),a=$("challenge-area"),review=inReview()?`<p class="mission-rule">Case review: get it right on your first try to fix this clue.</p>`:"";
 if(s.type==="mc")a.innerHTML=`<span class="mission-tag">${missionLabel(s.type)}</span><h2 class="challenge-title">Make the call</h2><p class="prompt">${s.prompt}</p>${review}<div class="choices" id="mc-choices"></div>`;
 if(s.type==="sort")a.innerHTML=`<span class="mission-tag">${missionLabel(s.type)}</span><h2 class="challenge-title">Break the pattern</h2><p class="prompt">${s.prompt}</p><p class="mission-rule">Place every card correctly. A mistake raises Christof’s Control.</p>${review}<div id="sort-board" class="sort-board"></div>`;
 if(s.type==="sequence")a.innerHTML=`<span class="mission-tag">${missionLabel(s.type)}</span><h2 class="challenge-title">Build the investigation</h2><p class="prompt">${s.prompt}</p><p class="mission-rule">Click each step in the correct order.</p>${review}<div class="sequence-list" id="seq-list"></div><button class="submit-btn" id="sequence-reset">Reset order</button>`;
 if(s.type==="multi")a.innerHTML=`<span class="mission-tag">${missionLabel(s.type)}</span><h2 class="challenge-title">File the charges</h2><p class="prompt">${s.prompt}</p><p class="mission-rule">More than one answer may be correct.</p>${review}<div class="choices" id="multi-choices"></div><button class="submit-btn" id="multi-submit">Submit evidence</button>`;
 if(s.type==="fill"){const saved=state.fills[s.key]||state.drafts[s.key]||[];a.innerHTML=`<span class="mission-tag">${missionLabel(s.type)}</span><h2 class="challenge-title">Finish the sentence</h2><p class="prompt">${s.prompt}</p><div class="fill-sentence">${s.parts.map((p,k)=>typeof p==="string"?`<span>${p}</span>`:p.sel?`<select class="fill-sel" data-k="${k}" aria-label="Choose one"><option value="">choose one ▾</option>${p.sel.map((o,j)=>`<option value="${j}">${o}</option>`).join("")}</select>`:`<input class="fill-in" data-k="${k}" maxlength="110" autocomplete="off" placeholder="${p.txt}" aria-label="${p.txt}">`).join("")}</div><button class="submit-btn send-btn" id="write-submit">Send transmission →</button><div id="write-model"></div>`;
  a.querySelectorAll("[data-k]").forEach(el=>{const k=+el.dataset.k;if(saved[k]!=null)el.value=saved[k];el.addEventListener("input",()=>{state.drafts[s.key]=fillValues(s);$("feedback").className="feedback";save()});el.addEventListener("change",()=>{state.drafts[s.key]=fillValues(s);save()});el.addEventListener("keydown",e=>{if(e.key==="Enter")submitFill()})});$("write-submit").addEventListener("click",submitFill);return}
 if(s.type==="mc")drawMC();if(s.type==="sequence")drawSequence();if(s.type==="multi")drawMulti();
 $("sequence-reset")?.addEventListener("click",resetSequence);$("multi-submit")?.addEventListener("click",submitMulti);
 if(s.type==="sort"){state.order=shuffle([...s.items.keys()]);renderSortCard()}}
function letter(i){return String.fromCharCode(65+i)}
function drawMC(){const s=current();state.order=freshOrder(s.choices.length,state.order);$("mc-choices").innerHTML=state.order.map((ci,pos)=>{const off=state.blocked.includes(ci);return `<button class="choice" data-choice="${ci}"${off?' disabled style="opacity:.35"':""}><span class="choice-letter">${letter(pos)}</span>${s.choices[ci]}</button>`}).join("");document.querySelectorAll("[data-choice]").forEach(b=>b.addEventListener("click",answerMC))}
function drawSequence(){const s=current();state.order=freshOrder(s.items.length,state.order);$("seq-list").innerHTML=state.order.map(i=>`<button class="sequence-item" data-seq="${i}"><span class="order">?</span>${s.items[i]}</button>`).join("");document.querySelectorAll("[data-seq]").forEach(b=>b.addEventListener("click",selectSequence))}
function drawMulti(){const s=current();state.order=freshOrder(s.choices.length,state.order);state.multi=new Set();$("multi-choices").innerHTML=state.order.map((ci,pos)=>`<button class="choice multi-choice" data-multi="${ci}"><span class="choice-letter">${letter(pos)}</span>${s.choices[ci]}</button>`).join("");document.querySelectorAll("[data-multi]").forEach(b=>b.addEventListener("click",toggleMulti))}

function showContinue(){setTimeout(()=>{try{$("continue-btn").scrollIntoView({block:"end",behavior:"smooth"})}catch{}},60)}
// ---------- Explain It (writing) ----------
// Not scored right/wrong and never sent to case review. A real answer is required to move on.
// After sending, the student sees a strong sample to compare with, and can still revise it on the turn-in screen.
function fillValues(s){return s.parts.map((p,k)=>{const el=document.querySelector(`[data-k="${k}"]`);return typeof p==="string"?null:(el?el.value:"")})}
function fillText(s,vals){return s.parts.map((p,k)=>typeof p==="string"?p:p.sel?(vals[k]===""||vals[k]==null?"___":p.sel[+vals[k]]):(String(vals[k]||"").trim()||"___")).join("").replace(/\s+/g," ").trim()}
function sampleVals(s){return s.parts.map(p=>typeof p==="string"?null:p.sel?String(p.sample):p.sample)}
const JUNKW=/\b(idk|idc|lol|lmao|bruh|asdf\w*|blah|dunno|whatever|stuff|things?|yeah|okay|ok|bro|dude|nothing|something)\b/gi;
// Each blank: something chosen / a few real words. No essays.
function fillProblem(s,vals){if(window.classIsTestT&&window.classIsTestT())return null;
 for(let k=0;k<s.parts.length;k++){const p=s.parts[k];if(typeof p==="string")continue;const v=String(vals[k]||"").trim();
  if(p.sel){if(v==="")return [k,"Choose an option from each dropdown."];continue}
  const w=(v.match(/[A-Za-zÀ-ÿ']+/g)||[]);if(!v)return [k,"Fill in every blank."];
  if(w.length<(p.min||1))return [k,`Use at least ${p.min} words in the “${p.txt}” blank.`];
  if((v.match(JUNKW)||[]).length>=1&&w.length<=(p.min||1)+1)return [k,"Use real details from the movie, not filler words."];
  if((v.match(JUNKW)||[]).length>=2)return [k,"Swap the filler words for real details from the movie."];
  if(p.need&&!p.need[0].test(v))return [k,p.need[1]]}
 if(s.diff){const [x,y,msg]=s.diff;if(String(vals[x]).trim().toLowerCase()===String(vals[y]).trim().toLowerCase())return [y,msg]}
 if(s.match){const [q,m,ok,msg]=s.match;if(!(ok[vals[q]]||[]).includes(+vals[m]))return [m,msg]}
 return null}
function showModel(s){const m=$("write-model");if(!m)return;document.querySelectorAll("[data-k]").forEach(el=>el.disabled=true);$("write-submit").disabled=true;
 m.innerHTML=`<div class="model-answer"><b>Compare yours to a strong answer:</b><p>${fillText(s,sampleVals(s))}</p></div>`}
function submitFill(){if(state.sceneDone)return;const s=current(),vals=fillValues(s),prob=fillProblem(s,vals);
 if(prob){const el=document.querySelector(`[data-k="${prob[0]}"]`);flash(`<span>${prob[1]}</span>`,false);if(el){el.classList.add("fill-flag");el.focus();setTimeout(()=>el.classList.remove("fill-flag"),1200)}tone(260,.08);return}
 state.fills[s.key]=vals;state.writing[s.key]=fillText(s,vals);delete state.drafts[s.key];state.sceneDone=true;
 if(s.evidence&&!state.evidence.includes(s.evidence))state.evidence.push(s.evidence);state.control=Math.max(0,state.control-4);
 flash(`<strong>Transmission sent.</strong> <span>On the test, an answer like this is worth 8 points.</span>`,true);showModel(s);
 $("continue-btn").textContent="Continue →";$("continue-btn").classList.remove("hidden");showContinue();renderEvidence();updateHUD();save();tone(640,.1)}

// ---------- Costs of a wrong pick ----------
function addControl(n){state.control=Math.min(100,state.control+n);if(state.control>=100){state.control=70;if(state.glitches>0){state.glitches=0;state.wipeNote=true}}updateHUD();save()}
function markMiss(){if(!state.sceneMissed){state.sceneMissed=true;if(!inReview()&&window.classFirstTry)classFirstTry.wrong();save()}}
// Lock the choices for a few seconds, then redraw them in a new order. Nothing stays red.
function jam(text,redraw){state.jammed=true;const area=$("challenge-area");area.querySelectorAll("button").forEach(b=>b.disabled=true);let left=(window.classIsTestT&&window.classIsTestT())?0:JAM_SECONDS;const wipe=state.wipeNote?`<span>Christof took full control of the signal and wiped out your Glitch Cards. Slow down: read the clue before you pick.</span><br>`:"";state.wipeNote=false;const tick=()=>{if(!state.jammed)return;if(left<=0){state.jammed=false;area.querySelectorAll("#multi-submit,#sequence-reset").forEach(x=>x.disabled=false);flash(`${wipe}<span>${text}</span> <span>Try again.</span>`,false);redraw();return}flash(`${wipe}<span>${text}</span> <strong>Christof jammed the signal.</strong> <span>New order in ${left}…</span>`,false);left--;setTimeout(tick,1000)};tick()}
// In case review, the first wrong move ends the try: show the key idea, send the clue to the back of the line.
function reviewMiss(){state.reviewMisses=(state.reviewMisses||0)+1;const s=current(),k=state.reviewQueue.shift();state.reviewQueue.push(k);$("challenge-area").querySelectorAll("button").forEach(b=>b.disabled=true);flash(`<strong>Not this time.</strong> <span>Key idea:</span> <span>${s.why}</span><br><span>This clue goes to the back of the line. You’ll see it again with the choices mixed up.</span>`,false);const cb=$("continue-btn");cb.classList.remove("hidden");let left=(window.classIsTestT&&window.classIsTestT())?0:6;cb.disabled=left>0;const t=()=>{if(left<=0){cb.disabled=false;cb.textContent="Next clue →";return}cb.textContent=`Read the key idea… ${left}`;left--;setTimeout(t,1000)};t();tone(180,.12);save()}

// ---------- Scoring ----------
function award(success=true){const s=current();success=success&&!state.hinted&&!state.sceneMissed;
 state.sceneDone=true;if(inReview()){state.reviewFixed++;state.reviewQueue.shift();save();return true}
 trackFirstTry(success);state.possible++;state.topicPossible[s.topic]=(state.topicPossible[s.topic]||0)+1;
 if(success){state.correct++;state.topicScores[s.topic]=(state.topicScores[s.topic]||0)+1;state.control=Math.max(0,state.control-3);if(s.evidence&&!state.evidence.includes(s.evidence))state.evidence.push(s.evidence)}
 else state.missed.push([state.chapter,state.scene]);
 if(s.ability&&!state.abilities.includes(s.ability))state.abilities.push(s.ability);renderEvidence();updateHUD();save();return success}
function flash(text,good){const f=$("feedback");f.className=`feedback show ${good?"good":"try"}`;f.innerHTML=text}
function completeScene(){const ok=award(true);const s=current();
 if(inReview())flash(`<strong>Clue fixed.</strong> <span>${s.why}</span>`,true);
 else flash(ok?`<strong>Evidence secured.</strong> <span>${s.why}</span>`:`<strong>Connection repaired.</strong> <span>No evidence this time, because it took more than one try.</span> <span>${s.why}</span>`,true);
 $("continue-btn").textContent=inReview()?(state.reviewQueue.length?"Next clue →":"Open the door →"):"Continue →";$("continue-btn").classList.remove("hidden");showContinue();tone(ok?620:480,.1)}

// ---------- Question types ----------
function answerMC(e){if(state.jammed)return;const s=current(),picked=+e.currentTarget.dataset.choice;state.attempts++;
 if(picked===s.answer){document.querySelectorAll("[data-choice]").forEach(b=>b.disabled=true);e.currentTarget.classList.add("correct");completeScene();return}
 markMiss();tone(180,.12);if(inReview())return reviewMiss();addControl(8);jam(state.attempts===1?"Not quite. Reread the clue and try another answer.":`Think about <strong>${s.idea||s.topic}</strong> and choose the most complete answer.`,drawMC)}
function renderSortCard(){const s=current(),board=$("sort-board");if(state.sortIndex>=s.items.length){completeScene();return}const item=s.items[state.order[state.sortIndex]];board.innerHTML=`<div class="sort-card"><small>CARD ${state.sortIndex+1} OF ${s.items.length}</small><p>${item.text}</p><div class="sort-actions">${s.categories.map((c,i)=>`<button data-sort="${i}">${c}</button>`).join("")}</div></div>`;board.querySelectorAll("[data-sort]").forEach(b=>b.addEventListener("click",answerSort))}
function answerSort(e){if(state.jammed)return;const s=current(),item=s.items[state.order[state.sortIndex]],picked=+e.currentTarget.dataset.sort;if(picked===item.answer){tone(600,.06);state.sortIndex++;renderSortCard();return}
 state.sortFirst=false;markMiss();tone(180,.12);if(inReview())return reviewMiss();addControl(5);const card=$("sort-board").firstElementChild;card.classList.add("wrong");setTimeout(()=>card.classList.remove("wrong"),300);jam("Not that category. Look at what the statement is mainly describing.",renderSortCard)}
function selectSequence(e){if(state.jammed||e.currentTarget.classList.contains("selected"))return;const idx=+e.currentTarget.dataset.seq;state.sequence.push(idx);e.currentTarget.classList.add("selected");e.currentTarget.querySelector(".order").textContent=state.sequence.length;tone(420+state.sequence.length*40,.04);if(state.sequence.length===current().items.length)checkSequence()}
function resetSequence(){if(state.jammed)return;state.sequence=[];document.querySelectorAll("[data-seq]").forEach(b=>{b.classList.remove("selected");b.querySelector(".order").textContent="?"})}
function checkSequence(){const s=current(),ok=s.order.every((x,i)=>x===state.sequence[i]);state.attempts++;if(ok){document.querySelectorAll("[data-seq]").forEach(b=>b.disabled=true);$("sequence-reset").disabled=true;completeScene();return}
 markMiss();tone(180,.12);if(inReview())return reviewMiss();addControl(10);state.sequence=[];jam("The study would break down in that order. Start with a question and background research, and write the hypothesis before you collect data.",drawSequence)}
function toggleMulti(e){if(state.jammed)return;const i=+e.currentTarget.dataset.multi;if(state.multi.has(i))state.multi.delete(i);else state.multi.add(i);e.currentTarget.classList.toggle("selected")}
function submitMulti(){if(state.jammed)return;const s=current(),picked=[...state.multi].sort((a,b)=>a-b),right=[...s.answers].sort((a,b)=>a-b);state.attempts++;const ok=picked.length===right.length&&picked.every((x,i)=>x===right[i]);if(ok){document.querySelectorAll("[data-multi]").forEach(b=>b.disabled=true);$("multi-submit").disabled=true;completeScene();return}
 markMiss();tone(180,.12);if(inReview())return reviewMiss();addControl(9);jam("At least one charge is missing or one selected choice is not an ethical problem. Recheck consent, privacy, and confidentiality.",drawMulti)}
function useHint(){if(state.glitches<1||state.inClear||state.phase!=="play"||state.jammed)return;state.hinted=true;state.glitches--;const s=current();if(s.type==="mc"){const wrong=shuffle(s.choices.map((c,i)=>i).filter(i=>i!==s.answer&&!state.blocked.includes(i)));state.blocked=state.blocked.concat(wrong.slice(0,Math.max(1,wrong.length-1)));document.querySelectorAll("[data-choice]").forEach(b=>{if(state.blocked.includes(+b.dataset.choice)){b.disabled=true;b.style.opacity=.35}});flash(`Signal intercepted: focus on <strong>${s.idea||s.topic}</strong>. Two choices have been blocked.`,true)}else if(s.type==="fill"){state.glitches++;flash(`Signal intercepted: pick from each dropdown, then type a few words in each box. Use a real detail from the movie.`,true)}else if(s.type==="sort")flash(`Signal intercepted: compare each card directly with the definitions of <strong>${s.categories.join(" and ")}</strong>.`,true);else if(s.type==="sequence")flash("Signal intercepted: begin with the research question. A hypothesis must come before data collection.",true);else flash("Signal intercepted: evaluate consent, privacy, confidentiality, harm, and the right to withdraw separately.",true);if(!state.blocked.length)state.blocked=[-1];updateHUD();save()}

// ---------- Moving through the story ----------
function renderChapterClear(restoring){state.inClear=true;if(!restoring){state.glitches++;state.control=Math.max(0,state.control-12)}const ch=chapters[state.chapter];$("story-text").innerHTML="";$("challenge-area").innerHTML=`<div class="chapter-clear"><span class="mission-tag">CHAPTER CLEARED</span><h2>${ch.title}</h2><p>You broke another layer of Christof’s control.${chapters[state.chapter+1]?` Next up: <b>${chapters[state.chapter+1].kicker}</b>.`:""}</p><div class="reward-card"><b>⚡</b><span>GLITCH CARD EARNED<br><small>Use it whenever you need a clue.</small></span></div></div>`;$("feedback").className="feedback";$("continue-btn").classList.remove("hidden");$("continue-btn").textContent="Enter Next Chapter →";updateHUD();save();if(!restoring)tone(720,.14)}
function score(){return state.correct/Math.max(1,state.possible)}
function renderLockedDoor(){state.phase="locked";const n=state.missed.length;
 $("chapter-kicker").textContent="THE EXIT DOOR";$("chapter-title").textContent="The door won’t open yet";$("scene-number").textContent="!!";$("scene-icon").textContent="🔒";$("scene-caption").textContent="EXIT DOOR • LOCKED";$("scene-visual").style.background="linear-gradient(135deg,#3b1d4f,#ef5e4f)";
 $("story-text").innerHTML=`<div class="speaker"><div class="portrait">C</div><div class="bubble"><b>CHRISTOF</b>You reached the door. But your case still has holes. Fix them, and the door is yours.</div></div>`;
 $("challenge-area").innerHTML=`<div class="chapter-clear"><span class="mission-tag">EXIT LOCKED</span><h2>Your case has ${n} hole${n===1?"":"s"}</h2><p>You don’t have to start over.</p><p><b>Fix the ${n} clue${n===1?"":"s"} you missed.</b> Get each one right on your first try, and the door opens.</p></div>`;
 $("feedback").className="feedback";$("continue-btn").textContent=`Fix my missed clues (${n}) →`;$("continue-btn").classList.remove("hidden");updateHUD();save()}
function startReview(){state.phase="review";state.reviewQueue=shuffle(state.missed.map(x=>x.slice()));state.reviewTotal=state.reviewQueue.length;state.reviewRounds++;state.reviewFixed=0;nextReview()}
function nextReview(){if(!state.reviewQueue.length){state.reviewDone=true;finish();return}[state.chapter,state.scene]=state.reviewQueue[0];renderScene()}
function advance(){if(state.phase==="locked"){startReview();return}if(state.phase==="review"){nextReview();return}
 if(state.inClear){state.inClear=false;state.chapter++;state.scene=0;renderScene();return}const ch=chapters[state.chapter];if(state.scene<ch.scenes.length-1){state.scene++;renderScene()}else if(state.chapter<chapters.length-1)renderChapterClear();else if(score()>=PASS||(window.classIsTestT&&window.classIsTestT()))finish();else renderLockedDoor()}
function finish(){clearInterval(state.timer);const first=state.phase!=="done";if(first){state.finalTime=fmtTime(elapsed());state.phase="done";state.turnedIn=false}$("meter-fill").style.width="100%";const pct=Math.round(score()*100);
 $("final-correct").textContent=`${state.correct}/${state.possible}`;$("final-evidence").textContent=state.evidence.length;$("final-score").textContent=pct+"%";$("final-time").textContent=state.finalTime||"—";
 $("end-message").innerHTML=`<span>${escH(state.name)}, you exposed the system behind Seahaven and walked through the door. Below: how ready you are for each part of the test.</span>`+(state.reviewDone?`<br><br><span>You fixed every clue you missed.</span>`:"");
 $("result-stamp").textContent="ESCAPED";
 const topics=[...new Set(chapters.flatMap(c=>c.scenes.map(s=>s.topic)))];$("mastery-report").innerHTML=`<p class="report-head">Your test, part by part (first-try clues)</p>`+topics.map(t=>{const a=state.topicScores[t]||0,p=state.topicPossible[t]||0,n=p?Math.round(a/p*100):0;return `<div class="mastery-row"><span>${t}</span><b class="${n>=70?"strong":"review"}">${n>=70?"Strong":"Review this"}</b></div>`}).join("");
 save();showScreen("end");renderTurnIn();if(first)tone(760,.18)}

// ---------- Start, resume, restart ----------
function nameOk(raw){const n=window.classShortName?classShortName(raw):String(raw).trim();return /^\S+ [A-Z]\.$/.test(n)?n:""}
function start(){const n=nameOk($("player-name").value);if(!n){$("name-msg").textContent="Type your first name and last initial, like Jordan M.";$("player-name").focus();return}
 let runs=0;try{runs=+localStorage.getItem(RUNS_KEY)||0;localStorage.setItem(RUNS_KEY,String(runs+1))}catch{}
 clearRun();Object.assign(state,{name:n,chapter:0,scene:0,correct:0,possible:0,evidence:[],abilities:[],topicScores:{},topicPossible:{},control:15,glitches:1,inClear:false,sceneMissed:false,blocked:[],phase:"play",missed:[],reviewQueue:[],reviewTotal:0,reviewRounds:0,reviewFixed:0,reviewMisses:0,reviewDone:false,sceneDone:false,turnedIn:false,finalTime:"",run:runs+1,elapsedBefore:0});
 buildMap();renderEvidence();showScreen("game");beginTimer();renderScene()}
function resume(){const o=loadRun();if(!o){start();return}restore(o);buildMap();renderEvidence();if(state.phase==="done"){finish();return}showScreen("game");beginTimer();
 if(state.phase==="locked")renderLockedDoor();else if(state.phase==="review")nextReview();else if(state.inClear){renderScene(true);renderChapterClear(true)}else renderScene(true)}
function startScreenNote(){const o=loadRun(),box=$("resume-box");if(!box)return;if(!o||o.phase==="done"){box.hidden=true;$("start-btn").innerHTML="Start the Broadcast <span>→</span>";return}
 let pos=0;for(let i=0;i<o.chapter;i++)pos+=chapters[i].scenes.length;pos+=o.scene+1;const nm=String(o.name||"").replace(/\.$/,"");
 $("resume-text").textContent=o.phase==="play"?`Welcome back, ${nm}. You’re on scene ${pos} of ${totalScenes}.`:o.phase==="locked"?`Welcome back, ${nm}. You reached the exit door. Fix your missed clues to open it.`:`Welcome back, ${nm}. You’re fixing missed clues: ${(o.reviewQueue||[]).length} left.`;
 box.hidden=false;$("start-btn").innerHTML="Keep going <span>→</span>";if(!$("player-name").value)$("player-name").value=o.name}
function tone(freq=480,duration=.06){if(!state.sound)return;try{const a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.frequency.value=freq;o.type="sine";g.gain.setValueAtTime(.05,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+duration)}catch{}}
$("start-btn").addEventListener("click",()=>{const o=loadRun();if(o&&o.phase!=="done")resume();else start()});
$("player-name").addEventListener("keydown",e=>{if(e.key==="Enter")$("start-btn").click()});
$("player-name").addEventListener("input",()=>{$("name-msg").textContent=""});
$("new-run-btn")?.addEventListener("click",()=>{if(confirm("Start a brand-new investigation? Your saved progress on this computer will be erased.")){clearRun();startScreenNote();start()}});
$("continue-btn").addEventListener("click",advance);$("hint-btn").addEventListener("click",useHint);
$("restart-btn").addEventListener("click",()=>{if(!confirm("Start a brand-new investigation? (Your turned-in work stays with your teacher.)"))return;clearRun();$("player-name").value=state.name||"";startScreenNote();showScreen("start")});
$("home-btn").addEventListener("click",()=>{save();clearInterval(state.timer);state.elapsedBefore=elapsed();state.startTime=0;startScreenNote();showScreen("start")});
$("sound-btn").addEventListener("click",e=>{state.sound=!state.sound;e.currentTarget.textContent=state.sound?"♪":"×";e.currentTarget.setAttribute("aria-label",state.sound?"Mute sound":"Turn on sound")});buildMap();
window.addEventListener("pagehide",()=>{if(state.phase!=="start")save()});

// ---------- Turn-in (teacher dashboard): one turn-in per run ----------
// The 4 Explain Its (one per test part) are the written work. Students can revise them here before turning in.
const STANDARD="Unit 1 review (matches the Unit 1 test, Parts 1–4): SS.9-12.Soc.1 (building a fair study), SS.9-12.Soc.2 (sociological perspective), SS.9-12.Soc.3 (research methods), SS.9-12.Soc.4 (theories and founders)";
const WRITES=chapters.flatMap(c=>c.scenes).filter(x=>x.type==="fill");
function trackFirstTry(success){if(!window.classFirstTry)return;const id="c"+state.chapter+"s"+state.scene;if(!success&&!state.sceneMissed)classFirstTry.wrong();classFirstTry.right(id)}
function weakTopics(){const topics=[...new Set(chapters.flatMap(c=>c.scenes.map(s=>s.topic)))];return topics.filter(t=>{const p=state.topicPossible[t]||0;return p&&(state.topicScores[t]||0)/p<.7})}
function escH(t){return String(t).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
function renderTurnIn(){let box=$("turnin-box");if(!box){box=document.createElement("section");box.id="turnin-box";box.className="turnin";$("mastery-report").after(box)}
 if(state.turnedIn){box.innerHTML=`<h2>Turn in your work</h2><p class="ti-done">✓ Turned in as ${escH(state.name.replace(/\.$/,""))}. Your teacher can see your work.</p>`;return}
 box.innerHTML=`<h2>Turn in your work</h2><p class="ti-small">Your 4 Explain Its:</p>`+WRITES.map(w=>`<div class="ti-answer"><b>${escH(w.short)}</b><p>${escH(state.writing[w.key]||"(not finished)")}</p></div>`).join("")+`<p class="ti-small">Turning in as <b>${escH(state.name)}</b></p><button id="turnInBtn" class="primary-btn">Turn in</button><p id="tiStatus" class="ti-status" role="status" aria-live="polite"></p>`;

 $("turnInBtn").onclick=async()=>{const st=$("tiStatus"),btn=$("turnInBtn");
  const miss=WRITES.find(w=>!state.writing[w.key]&&!(window.classIsTestT&&window.classIsTestT()));if(miss){st.textContent=miss.short.split(" · ")[0]+" isn’t finished yet.";return}
  if(!window.classTurnIn){st.textContent="Turn-in is not available right now. Tell your teacher.";return}
  btn.disabled=true;st.textContent="Turning in…";const review=weakTopics(),pct=Math.round(score()*100);
  const escaped=state.reviewDone?`After fixing ${state.reviewTotal} missed clue${state.reviewTotal===1?"":"s"} (${state.reviewMisses||0} wrong tries during review)`:`Yes, ${pct}% on the first try`;
  const answers={Standard:STANDARD,"First-try correct":state.correct+" of "+state.possible,"This run":state.correct+" of "+state.possible+" first try ("+pct+"%)","Escaped":escaped,"Run on this computer":"#"+(state.run||1),"Time":state.finalTime||"","Test parts to review":review.length?review.join(", "):"None (70%+ on every part)"};
  WRITES.forEach(w=>answers[w.label]=state.writing[w.key]||"");
  try{const res=await classTurnIn("https://fynn-class-assignment-submissions-20261024.neotboy.chatgpt.site/api/submit",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({studentName:state.name,assignmentId:"sociology-unit1-review-seahaven",answers})});
   const d=await res.json().catch(()=>({}));if(!res.ok)throw new Error(d.error||"Your work did not save. Try again.");
   state.turnedIn=true;save();renderTurnIn()}
  catch(e){st.textContent=e.message;btn.disabled=false}}}
startScreenNote();
(function(){const o=loadRun();if(o&&o.phase==="done"){restore(o);buildMap();renderEvidence();finish()}})();

// ---------------- Test T. skip bar (shared/turnin.js) ----------------
// The teacher signed in as Test T. can jump to any scene or answer the current clue.
try{
 const testPos=i=>{let c=0,n=i;while(c<chapters.length-1&&n>=chapters[c].scenes.length){n-=chapters[c].scenes.length;c++}return [c,n]};
 (window.classTestHooks=window.classTestHooks||[]).push({
  count:()=>totalScenes+1,
  index:()=>state.phase==="done"?totalScenes:state.phase==="start"?0:Math.max(0,Math.min(progressIndex(),totalScenes-1)),
  label:i=>{if(i>=totalScenes)return "Ending + turn in";const [c,n]=testPos(i);return `${c+1}.${n+1} ${chapters[c].title}`},
  go:i=>{if(!state.name)state.name="Test T.";buildMap();renderEvidence();clearInterval(state.timer);state.elapsedBefore=elapsed();state.startTime=0;
   if(i>=totalScenes){if(state.phase!=="done")state.phase="play";state.inClear=false;state.jammed=false;finish();return}
   const [c,n]=testPos(i);state.chapter=c;state.scene=n;state.phase="play";state.inClear=false;state.jammed=false;
   showScreen("game");beginTimer();renderScene()},
  solve:()=>{if(state.inClear||state.sceneDone||(state.phase!=="play"&&state.phase!=="review"))return;const s=current();state.jammed=false;
   if(s.type==="mc"){const b=document.querySelector(`[data-choice="${s.answer}"]`);if(b){b.disabled=false;b.click()}}
   else if(s.type==="sort"){state.sortIndex=s.items.length;renderSortCard()}
   else if(s.type==="sequence"){state.sequence=s.order.slice();checkSequence()}
   else if(s.type==="multi"){state.multi=new Set(s.answers);submitMulti()}
   else if(s.type==="fill"){const v=sampleVals(s);document.querySelectorAll("[data-k]").forEach(el=>el.value=v[+el.dataset.k]);submitFill()}}
 });
 if(window.classTestSkip)window.classTestSkip.refresh();
}catch(e){}
